RegisterEvent(25, "Ward lamp", function(continueStep)
    if continueStep == 2 then
        SetValue(MapVar(4), 1)
        evt.SetLight(1, 0)
        evt.SetSprite(1, 0)
        if IsAtLeast(MapVar(5), 1) then
            evt.StatusText("The ward flickers and goes out.")
        else
            evt.StatusText("The ward thins, but holds.")
        end
        return
    end
    if continueStep ~= nil then
        return
    end
    if not (not (IsAtLeast(MapVar(4), 1))) then
        evt.StatusText("The lamp is out.")
        return
    end
    evt.SetMessage("A ward lamp. Its cold violet flame leans toward Morgana's door.")
    evt.AskQuestion(25, 1, 0, 2, "Snuff it (Yes/No)?", {"Yes", "Y"})
end, "Ward lamp")

